# limit BLAS threads (thread thrash made 10 s/turn on a loaded box)
def _limit_threads():
    import ctypes, glob as _gl, os as _os
    try:
        import numpy as _np
        d = _os.path.join(_os.path.dirname(_np.__file__), "..", "numpy.libs")
        for lib in _gl.glob(_os.path.join(d, "*openblas*")):
            L = ctypes.CDLL(lib)
            for fn in ("scipy_openblas_set_num_threads64_", "openblas_set_num_threads64_", "openblas_set_num_threads", "scipy_openblas_set_num_threads"):
                if hasattr(L, fn):
                    getattr(L, fn)(1)
    except Exception:
        pass
_limit_threads()
# ---------------- numpy runtime (generated by lab/bc/export.py) ----------------
import base64 as _b64, io as _io, zlib as _zlib
_W = dict(np.load(_io.BytesIO(_zlib.decompress(_b64.b85decode(_WBLOB)))))
_TEAM_VEC = np.zeros(len(_TEAMS), np.float32); _TEAM_VEC[_TEAMS.index(_TEAM)] = 1

def _conv(x, w, b):
    c, H, Wd = x.shape; o = w.shape[0]
    xp = np.pad(x, ((0, 0), (1, 1), (1, 1)))
    cols = np.stack([xp[:, i:i + H, j:j + Wd] for i in range(3) for j in range(3)], 1)  # c,9,H,W
    cols = cols.reshape(c * 9, H * Wd)
    return (w.reshape(o, c * 9) @ cols).reshape(o, H, Wd) + b[:, None, None]

def _relu(x): return np.maximum(x, 0)

def _forward(Bd, g, units):
    x = np.concatenate([Bd, np.broadcast_to(g[:, None, None], (len(g), 10, 10))], 0).astype(np.float32)
    h = _relu(_conv(x, _W["inp.weight"], _W["inp.bias"]))
    for k in range(_NBLOCKS):
        a = _relu(_conv(h, _W[f"body.{k}.a.weight"], _W[f"body.{k}.a.bias"]))
        h = _relu(h + _conv(a, _W[f"body.{k}.b.weight"], _W[f"body.{k}.b.bias"]))
    outs = []; tls = []; hf = h.reshape(h.shape[0], -1)
    for (ux, uy, uv) in units:
        z0 = np.concatenate([h[:, uy, ux], uv, g])
        z = _relu(_W["unit.0.weight"] @ z0 + _W["unit.0.bias"]); outs.append(_W["unit.2.weight"] @ z + _W["unit.2.bias"])
        if "tq.0.weight" in _W:
            q = _W["tq.2.weight"] @ _relu(_W["tq.0.weight"] @ z0 + _W["tq.0.bias"]) + _W["tq.2.bias"]
            tls.append(q @ hf / np.sqrt(h.shape[0]))
    pooled = np.concatenate([h.mean((1, 2)), h.max((1, 2)), g])
    m = _relu(_W["mkt.0.weight"] @ pooled + _W["mkt.0.bias"]); m = (_W["mkt.2.weight"] @ m + _W["mkt.2.bias"]).reshape(len(MKT_KEYS), MKT_MAX + 1)
    return outs, m, tls

_MOVES = {"NORTH": (0, -1), "SOUTH": (0, 1), "EAST": (1, 0), "WEST": (-1, 0)}

_SEED_COST = {"WHEAT": 10, "CARROT": 20, "TOMATO": 50, "STRAWBERRY": 100, "MELON": 80}
_ANIMAL_COST = {"GOOSE": 300, "COW": 400, "SHEEP": 500}
_LAND_COST = [1000, 2000, 4000]

def _fib(n):
    a, b = 1, 1
    for _ in range(n): a, b = b, a + b
    return a

def _legal_mask(obs, p, x, y, inv, shed_left, seeds):
    farm = obs["farms"][p]; t = farm["tiles"][y][x]; m = np.ones(len(UNIT_OPS), bool)
    for mv, (dx, dy) in _MOVES.items():
        nx, ny = x + dx, y + dy
        if not (0 <= nx < 10 and 0 <= ny < 10) or farm["tiles"][ny][nx] == "LOCKED": m[UNIT_IDX[mv]] = False
    is_plant = isinstance(t, dict) and t.get("kind") == "PLANT"
    if not is_plant:
        for op in ("WATER", "HARVEST", "FERTILIZE"): m[UNIT_IDX[op]] = False
    if not (inv or {}).get("FERTILIZER"): m[UNIT_IDX["FERTILIZE"]] = False
    has_animal = isinstance(t, dict) and t.get("animal") in ANIMALS
    if not has_animal:
        for op in ("FEED", "CARE", "COLLECT_FERTILIZER"): m[UNIT_IDX[op]] = False
    if not (inv or {}).get("WHEAT"): m[UNIT_IDX["FEED"]] = False
    for c in CROPS:
        if t is not None or seeds.get(c, 0) <= 0: m[UNIT_IDX["PLANT:" + c]] = False
    if t is not None: m[UNIT_IDX["BUILD_COOP"]] = m[UNIT_IDX["BUILD_PASTURE"]] = False
    if t is None or (isinstance(t, dict) and t.get("kind") not in ("WEED", "PLANT")): m[UNIT_IDX["DIG"]] = False
    adj = (x, y) in SHED_ADJ
    if not adj or not inv: m[UNIT_IDX["DROP"]] = False
    for it in ITEMS:
        if not adj or shed_left.get(it, 0) <= 0: m[UNIT_IDX["PICKUP:" + it]] = False
        if not (inv or {}).get(it): m[UNIT_IDX["PLACE:" + it]] = False
    return m

_PICK_N = {"WHEAT": 3, "FERTILIZER": 4}

def _decode_unit(cls, inv, shed_left):
    k = UNIT_OPS[int(cls)]
    if ":" not in k: return [k]
    op, it = k.split(":")
    if op == "PLANT": return ["PLANT", it]
    if op == "PICKUP":
        n = 1 if it in ANIMALS else min(_PICK_N.get(it, 3), shed_left.get(it, 1)); shed_left[it] = shed_left.get(it, 0) - n
        return ["PICKUP", it, max(1, n)]
    n = 1 if (it in ANIMALS or it == "FERTILIZER") else int((inv or {}).get(it, 1))
    return ["PLACE", it, max(1, n)]

def _afford(obs, p, orders):
    farm = obs["farms"][p]; money = float(farm["money"]); prices = obs["market"].get("prices") or {}
    hires = int(farm.get("hires_today", 0) or 0); nland = len(farm.get("unlocked_quadrants") or []) - 1; out = []
    for o in orders:
        op = o[0]
        if op == "SELL": out.append(o); continue
        if op == "HIRE": c = _fib(hires)
        elif op == "BUY_LAND": c = _LAND_COST[nland] if 0 <= nland < 3 else 1e12
        elif op == "BUY_SEED": c = _SEED_COST.get(o[1], 1e9) * o[2]
        elif op == "BUY_ANIMAL": c = _ANIMAL_COST.get(o[1], 1e9) * o[2]
        else: c = float(prices.get(o[1], 100)) * 1.2 * o[2]
        if c <= money:
            money -= c; out.append(o)
            if op == "HIRE": hires += 1
            if op == "BUY_LAND": nland += 1
    return out

def agent(obs, config=None):
    try:
        p = int(obs.get("player", 0))
        Bd = board_tensor(obs, p); g = np.concatenate([glob_vec(obs, p), _TEAM_VEC])
        ul = unit_list(obs, p); priv = obs.get("private") or {}
        outs, m, tls = _forward(Bd, g, ul)
        tiles = obs["farms"][p]["tiles"]
        locked = np.array([[tiles[yy][xx] == "LOCKED" for xx in range(10)] for yy in range(10)]).reshape(-1)
        invs = priv.get("inventories") or []; shed_left = dict(priv.get("shed") or {}); seeds = dict(priv.get("seeds") or {})
        acts = []
        for i, ((x, y, v), lg) in enumerate(zip(ul, outs)):
            inv = invs[i] if i < len(invs) else {}
            legal = _legal_mask(obs, p, x, y, inv, shed_left, seeds)
            a = None
            if tls:
                tl = np.where(locked, -1e9, tls[i]); tcell = int(tl.argmax()); tx, ty = tcell % 10, tcell // 10
                if (tx, ty) != (x, y):
                    cand = []
                    if tx > x: cand.append("EAST")
                    if tx < x: cand.append("WEST")
                    if ty > y: cand.append("SOUTH")
                    if ty < y: cand.append("NORTH")
                    cand = [c for c in cand if legal[UNIT_IDX[c]]]
                    if cand: a = [max(cand, key=lambda c: lg[UNIT_IDX[c]])]
                else:
                    for mv in _MOVES: legal[UNIT_IDX[mv]] = False
            if a is None:
                lg2 = np.where(legal, lg, -1e9); a = _decode_unit(int(lg2.argmax()), inv, shed_left)
            if a[0] == "PLANT": seeds[a[1]] = seeds.get(a[1], 0) - 1
            acts.append(a)
        orders = _afford(obs, p, decode_market(m.argmax(1)))
        return {"farmer": acts[0] if acts else ["PASS"], "hands": acts[1:], "market": orders}
    except Exception:
        return {"farmer": ["PASS"], "hands": [], "market": []}
